const message = $input.first().json.message;
const text = (message && message.text) || '';
if (!/^\/hotnews(?:@\w+)?\s*$/i.test(text)) {
  return []; // not a bare /hotnews command -- ignore
}
return [{ json: { chat_id: String(message.chat.id) } }];

const message = $input.first().json.message;
const text = (message && message.text) || '';
const match = text.match(/^\/hotcollect(?:@\w+)?\s+(\d{4}-\d{2}-\d{2})\s*$/i);
if (!match) {
  return []; // not a /hotcollect command, or missing the required date -- ignore
}
return [{ json: { target_date: match[1], chat_id: String(message.chat.id) } }];

const message = $input.first().json.message;
const text = (message && message.text) || '';
// A bare comma/space separated number list, e.g. '1,3,7' -- how a broadcast reply looks.
const match = text.match(/^\s*\d+(?:\s*[,\s]\s*\d+)*\s*$/);
if (!match) {
  return [];
}
return [{ json: { selection: text.trim(), chat_id: String(message.chat.id) } }];

// Per-item mode: pairs this feed's parsed XML back with which outlet it came from
// via $('RSS Feed List').item.
const outlet = $('RSS Feed List').item.json.outlet;
const channel = $json.rss && $json.rss.channel;
const ch = Array.isArray(channel) ? channel[0] : channel;
const rawItems = ch && ch.item;
const items = Array.isArray(rawItems) ? rawItems : (rawItems ? [rawItems] : []);
const pick = (obj, key) => {
  const v = obj && obj[key];
  return Array.isArray(v) ? v[0] : v;
};
const decodeEntities = (s) => String(s || '')
  .replace(/&quot;/g, '"')
  .replace(/&#0?39;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&amp;/g, '&');
const WINDOW_MS = 2 * 3600 * 1000; // last 2 hours -- matches the hourly schedule, with a buffer
const cutoff = Date.now() - WINDOW_MS;
const articles = items
  .filter(it => {
    const t = new Date(pick(it, 'pubDate')).getTime();
    return !isNaN(t) && t >= cutoff;
  })
  .map(it => ({
    outlet,
    title: decodeEntities(pick(it, 'title')).replace(/<[^>]+>/g, ''),
    url: pick(it, 'link') || ''
  }));
return { json: { outlet, articles } };

const items = $input.all().map(i => i.json); // [{outlet, title, url}, ...]
if (items.length === 0) {
  return [{ json: { empty: true } }];
}
const lines = items.map((it, idx) => `${idx}. [${it.outlet}] ${it.title}`);
return [{ json: { empty: false, items, prompt_list: lines.join('\n') } }];

