const response = $input.first().json;
const toolUse = (response.content || []).find(c => c.type === 'tool_use');
if (!toolUse) {
  return [{ json: { empty: true } }];
}
const items = $('Build Clustering Prompt Input').first().json.items;
const clusters = (toolUse.input.clusters || [])
  .map(c => {
    const members = (c.member_indices || []).map(i => items[i]).filter(Boolean);
    const outlets = [...new Set(members.map(m => m.outlet))];
    const rep = members[0];
    return {
      topic: c.topic,
      outlet_count: outlets.length,
      outlets,
      article_title: rep ? rep.title : c.topic,
      article_url: rep ? rep.url : null
    };
  })
  .filter(c => c.outlet_count >= 2 && c.article_url)
  .sort((a, b) => b.outlet_count - a.outlet_count)
  .slice(0, 10);
if (clusters.length === 0) {
  return [{ json: { empty: true } }];
}
const candidateDate = new Date(Date.now() + 9 * 60 * 60 * 1000).toISOString().slice(0, 10); // KST 'today'
return clusters.map(c => ({
  json: {
    empty: false,
    keyword: c.topic,
    rank: null,
    approx_traffic: null,
    trend_link: null,
    outlet_count: c.outlet_count,
    article_title: c.article_title,
    article_url: c.article_url,
    article_source: c.outlets.join(', '),
    region: 'KR',
    candidate_date: candidateDate
  }
}));

const root = $input.first().json.rss.channel;
const channel = Array.isArray(root) ? root[0] : root;
const rawItems = channel.item;
const items = Array.isArray(rawItems) ? rawItems : [rawItems];
const trendDate = new Date(Date.now() + 9 * 60 * 60 * 1000).toISOString().slice(0, 10); // KST date, not UTC

const pick = (obj, key) => {
  const v = obj?.[key];
  return Array.isArray(v) ? v[0] : v;
};

const results = items.slice(0, 20).map((item, idx) => ({
  json: {
    rank: idx + 1,
    keyword: pick(item, 'title') || '',
    approx_traffic: pick(item, 'ht:approx_traffic') || null,
    trend_link: pick(item, 'link') || '',
    region: 'KR',
    trend_date: trendDate
  }
}));

return results;

// VERIFY IN UI: 'ht:approx_traffic' field naming depends on how the XML node
// namespaces tags in your n8n version.

const ctx = $('Parse Hotcollect Command').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.trend_date === ctx.target_date);
rows.sort((a, b) => (a.rank ?? 999) - (b.rank ?? 999));
const top = rows.slice(0, 20);
if (top.length === 0) {
  return [{ json: { empty: true } }];
}
return top.map(r => ({
  json: {
    empty: false,
    keyword: r.keyword,
    rank: r.rank,
    approx_traffic: r.approx_traffic,
    trend_link: r.trend_link,
    candidate_date: ctx.target_date
  }
}));

const ctx = $('Rank Collector Keywords').item.json;
const response = $json;
const items = response.items || [];
const decodeEntities = (s) => s
  .replace(/&quot;/g, '"')
  .replace(/&#0?39;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&amp;/g, '&');
const articles = items.slice(0, 3).map(a => ({
  keyword: ctx.keyword,
  rank: ctx.rank,
  approx_traffic: ctx.approx_traffic,
  trend_link: ctx.trend_link,
  article_title: decodeEntities((a.title || '').replace(/<[^>]+>/g, '')),
  article_url: a.originallink || a.link,
  article_source: 'naver_news',
  published_at: a.pubDate,
  outlet_count: null,
  region: 'KR',
  candidate_date: ctx.candidate_date
}));
return { json: { articles } };

// Convergence point for the 3-hourly broadcast schedule and the on-demand /hotnews command.
let chat_id;
try {
  $('Schedule Trigger (Broadcast)').first();
  chat_id = 'REPLACE_WITH_YOUR_CHAT_ID';
} catch (e) {
  chat_id = $('Parse Hotnews Command').first().json.chat_id;
}
return [{ json: { chat_id } }];

const ctx = $('Broadcast Trigger Context').first().json;
const rows = $input.all().map(i => i.json).filter(r => !r.posted_at);
rows.sort((a, b) => {
  if (a.candidate_date !== b.candidate_date) return a.candidate_date < b.candidate_date ? 1 : -1;
  const aOutlet = a.outlet_count ?? -1;
  const bOutlet = b.outlet_count ?? -1;
  if (aOutlet !== bOutlet) return bOutlet - aOutlet;
  return (a.rank ?? 999) - (b.rank ?? 999);
});
const top = rows.slice(0, 20);
if (top.length === 0) {
  return [{ json: { empty: true, chat_id: ctx.chat_id } }];
}
return [{
  json: {
    empty: false,
    chat_id: ctx.chat_id,
    items: top.map((r, i) => ({
      index: i + 1,
      candidate_id: r.id,
      keyword: r.keyword,
      trend_link: r.trend_link,
      candidate_date: r.candidate_date,
      article_title: r.article_title,
      article_url: r.article_url,
      outlet_count: r.outlet_count
    }))
  }
}];

const d = $input.first().json;
const lines = d.items.map(it => {
  const corroboration = it.outlet_count ? ` (${it.outlet_count}개 매체 보도)` : '';
  return `${it.index}. [${it.keyword}] (${it.candidate_date})${corroboration}\n   ${it.article_title}`;
});
return [{
  json: {
    chat_id: d.chat_id,
    items: d.items,
    list_text: lines.join('\n')
  }
}];

const rows = $input.all().map(i => i.json);
const latest = rows.sort((a, b) => b.id - a.id)[0];
const built = $('Build Broadcast List').first().json;
return [{ json: { id: latest.id, chat_id: built.chat_id, items: built.items, list_text: built.list_text, attempt: 1 } }];

const input = $input.first().json;
return [{
  json: {
    id: input.id,
    chat_id: input.chat_id,
    items: input.items,
    list_text: input.list_text,
    attempt: input.attempt || 1
  }
}];

const attemptData = $('Broadcast Attempt').first().json;
const query = ($json.query) || {};
const raw = query.selection;
if (typeof raw === 'undefined') {
  const MAX_ATTEMPTS = 3;
  if (attemptData.attempt >= MAX_ATTEMPTS) {
    return [{ json: { ...attemptData, outcome: 'drop' } }];
  }
  return [{ json: { ...attemptData, attempt: attemptData.attempt + 1, outcome: 'retry' } }];
}
const indices = String(raw).split(/[,\s]+/).map(s => s.trim()).filter(Boolean).map(n => parseInt(n, 10)).filter(n => !isNaN(n));
const selected = (attemptData.items || []).filter(it => indices.includes(it.index));
if (selected.length === 0) {
  return [{ json: { ...attemptData, outcome: 'invalid' } }];
}
return selected.map(it => ({ json: { outcome: 'selected', ...it } }));

return $input.all().map(i => ({
  json: {
    id: i.json.candidate_id,
    keyword: i.json.keyword,
    trend_link: i.json.trend_link || null,
    reference_date: i.json.candidate_date,
    original_title: i.json.article_title || null,
    original_url: i.json.article_url || null
  }
}));

const items = $input.all();
const keywords = items.map(i => i.json.keyword).join(', ');
return [{ json: { count: items.length, keywords } }];

const selection = $('Parse Numeric Reply').first().json.selection;
const rows = $input.all().map(i => i.json);
const pending = rows.filter(r => r.pending_resume_url).sort((a, b) => b.id - a.id)[0];
if (!pending) {
  return []; // nothing currently waiting on a broadcast reply -- ignore this message
}
return [{ json: { selection, resume_url: pending.pending_resume_url, id: pending.id } }];

// Single entry point in this standalone workflow -- no try/catch needed, unlike
// Daily Posting's Keyword Context which juggles 3 sources in one shared workflow.
const source = $('Execute Workflow Trigger (Item)').first().json;
return [{
  json: {
    id: source.id,
    keyword: source.keyword,
    trend_link: source.trend_link || null,
    source: 'hotnews',
    reference_date: source.reference_date || null,
    original_title: source.original_title || null,
    original_url: source.original_url || null
  }
}];

const keywordCtx = $('Keyword Context').first().json;
const response = $input.first().json;
const articles = response.items || [];

const decodeEntities = (s) => s
  .replace(/&quot;/g, '"')
  .replace(/&#0?39;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&amp;/g, '&');

// Anchored to the SELECTED ARTICLE's own date, not 'now' -- a /hotcollect backfill can be
// a year old, and a 'last N days from today' cutoff would filter out every real related
// article. Window is +-14 days around that date, matching how news coverage of an event
// actually clusters in time.
const center = new Date(keywordCtx.reference_date).getTime();
const WINDOW_MS = 14 * 24 * 3600 * 1000;
const recent = articles
  .filter(a => {
    const t = new Date(a.pubDate).getTime();
    return !isNaN(t) && Math.abs(t - center) <= WINDOW_MS;
  })
  .map(a => ({
    keyword_id: keywordCtx.id,
    title: decodeEntities((a.title || '').replace(/<[^>]+>/g, '')),
    url: a.originallink || a.link,
    source: 'naver_news',
    published_at: a.pubDate
  }));

// Always guarantee the originally-selected article itself counts as 'found', even if the
// live re-search above turns up nothing else in-window (very plausible for older dates).
const alreadyIncluded = recent.some(r => r.url === keywordCtx.original_url);
if (keywordCtx.original_url && !alreadyIncluded) {
  recent.unshift({
    keyword_id: keywordCtx.id,
    title: keywordCtx.original_title,
    url: keywordCtx.original_url,
    source: 'naver_news',
    published_at: keywordCtx.reference_date
  });
}

// Always return exactly ONE item (even when recent.length === 0) -- n8n skips downstream
// nodes entirely when an item count hits zero, which would silently kill the 'no recent
// news' Telegram notification.
return [{ json: { keyword_id: keywordCtx.id, count: recent.length, articles: recent } }];

const keywordCtx = $('Keyword Context').first().json;
const agg = $input.first().json;
const titles = agg.title || [];
const urls = agg.url || [];
const newsLines = titles.map((t, i) => `${i + 1}. ${t}\n   ${urls[i] || ''}`).join('\n') || '(관련 뉴스 없음)';

return [{
  json: {
    id: keywordCtx.id,
    keyword: keywordCtx.keyword,
    trend_link: keywordCtx.trend_link,
    news_list: newsLines
  }
}];

// Loop entry point: reached either from Build News Summary (attempt starts at 1)
// or from IF News Retry looping back (attempt already incremented).
const input = $input.first().json;
return [{
  json: {
    id: input.id,
    keyword: input.keyword,
    trend_link: input.trend_link,
    news_list: input.news_list,
    attempt: input.attempt || 1
  }
}];

const attemptData = $('News Review Attempt').first().json;
const hasDecision = $json.query && typeof $json.query.decision !== 'undefined';

if (hasDecision) {
  return [{
    json: {
      ...attemptData,
      outcome: $json.query.decision === 'approve' ? 'proceed' : 'rejected',
      comment: $json.query.comment || null
    }
  }];
}

const MAX_ATTEMPTS = 5;
if (attemptData.attempt >= MAX_ATTEMPTS) {
  return [{ json: { ...attemptData, outcome: 'proceed', auto_approved: true, comment: null } }];
}
return [{ json: { ...attemptData, attempt: attemptData.attempt + 1, outcome: 'retry' } }];

const response = $input.first().json;
const toolUse = (response.content || []).find(c => c.type === 'tool_use');
if (!toolUse) {
  throw new Error('Claude 응답에 tool_use가 없습니다: ' + JSON.stringify(response));
}
return [{ json: toolUse.input }];

const item = $input.first().json;
const html = typeof item === 'string' ? item : (item.data || '');
const patterns = [
  /<meta[^>]+property=["']og:image["'][^>]*content=["']([^"']+)["']/i,
  /<meta[^>]+content=["']([^"']+)["'][^>]*property=["']og:image["']/i
];
let imageUrl = null;
for (const re of patterns) {
  const m = html.match(re);
  if (m) { imageUrl = m[1]; break; }
}
// News sites frequently emit meta content as HTML-escaped (e.g. '&amp;' between
// query params), which breaks n8n's query-string parser on the download request.
if (imageUrl) {
  imageUrl = imageUrl
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}
return [{ json: { found: !!imageUrl, imageUrl } }];

const response = $input.first().json;
const photo = (response.photos || [])[0];
if (!photo) {
  return [{ json: { found: false } }];
}
return [{
  json: {
    found: true,
    imageUrl: photo.src.large2x || photo.src.original,
    photographer: photo.photographer,
    photographerUrl: photo.photographer_url
  }
}];

// Reached from either Upload Featured Image to WordPress's response (has an 'id')
// or IF Image Found's false branch (the {found:false} passthrough, no 'id') --
// either way, exactly one item arrives here.
const item = $input.first().json;
return [{ json: { featured_media: item.id || 0 } }];

const response = $input.first().json;
const photo = (response.photos || [])[0];
if (!photo) {
  return [{ json: { found: false } }];
}
return [{ json: { found: true, imageUrl: photo.src.large2x || photo.src.original } }];

const response = $input.first().json;
const photo = (response.photos || [])[0];
if (!photo) {
  return [{ json: { found: false } }];
}
return [{ json: { found: true, imageUrl: photo.src.large2x || photo.src.original } }];

const bodyHtml = $('Parse Claude Response').first().json.body_html;

let img1 = null, img2 = null;
try { img1 = $('Upload Body Image 1').first().json.source_url; } catch (e) {}
try { img2 = $('Upload Body Image 2').first().json.source_url; } catch (e) {}
const images = [img1, img2].filter(Boolean);

if (images.length === 0) {
  return [{ json: { body_html: bodyHtml } }];
}

// Split right after each closing </p> so images land between paragraphs, not mid-sentence.
const paragraphs = bodyHtml.split(/(?<=<\/p>)/i).filter(p => p.trim());
const total = paragraphs.length;
const buildImg = (url) => `<figure style="width:100%;text-align:center;margin:1.5em 0;"><img src="${url}" alt="" style="width:100%;height:auto;display:block;margin:0 auto;" /></figure>`;

if (images.length === 1 || total < 3) {
  const at = Math.max(1, Math.floor(total / 2));
  paragraphs.splice(at, 0, buildImg(images[0]));
} else {
  const at1 = Math.max(1, Math.floor(total / 3));
  const at2 = Math.max(at1 + 1, Math.floor((total * 2) / 3));
  paragraphs.splice(at2, 0, buildImg(images[1]));
  paragraphs.splice(at1, 0, buildImg(images[0]));
}

return [{ json: { body_html: paragraphs.join('') } }];

const response = $input.all().map(i => i.json);
const targetName = $('Parse Claude Response').first().json.category;
const match = response.find(c => c.name === targetName);
return [{ json: { found: !!match, id: match ? match.id : null, name: targetName } }];

const claudeTags = $('Parse Claude Response').first().json.tags || [];
const existingTags = $input.all().map(i => i.json);
const existingByName = new Map(existingTags.map(t => [String(t.name).toLowerCase(), t.id]));
const resolvedIds = [];
const missingNames = [];
for (const name of claudeTags) {
  const id = existingByName.get(String(name).toLowerCase());
  if (id) resolvedIds.push(id);
  else missingNames.push(name);
}
if (missingNames.length === 0) {
  return [{ json: { needsCreate: false, resolvedIds } }];
}
return missingNames.map(name => ({ json: { needsCreate: true, name, resolvedIds } }));

const item = $input.first().json;
const id = item.id || (item.data && item.data.term_id) || null;
return [{ json: { id } }];

const createdIds = ($input.first().json.id || []);
const resolvedIds = $('Resolve Tag IDs').first().json.resolvedIds || [];
return [{ json: { tag_ids: [...resolvedIds, ...createdIds] } }];

const item = $input.first();
const b64 = (item.binary && item.binary.data && item.binary.data.data) || '';
const bytes = Math.floor(b64.length * 3 / 4);
const MAX_BYTES = 1500 * 1024;
return [{ json: { ...item.json, tooLarge: bytes > MAX_BYTES, sizeBytes: bytes }, binary: item.binary }];

const item = $input.first();
const b64 = (item.binary && item.binary.data && item.binary.data.data) || '';
const bytes = Math.floor(b64.length * 3 / 4);
const MAX_BYTES = 1500 * 1024;
return [{ json: { ...item.json, tooLarge: bytes > MAX_BYTES, sizeBytes: bytes }, binary: item.binary }];

const item = $input.first();
const b64 = (item.binary && item.binary.data && item.binary.data.data) || '';
const bytes = Math.floor(b64.length * 3 / 4);
const MAX_BYTES = 1500 * 1024;
return [{ json: { ...item.json, tooLarge: bytes > MAX_BYTES, sizeBytes: bytes }, binary: item.binary }];

// Picks a CONCRETE intro style+phrasing directive (not an abstract 'be different'
// instruction, which an audit found Claude ignores in practice -- every post converged
// on the same 'everyday scene -> topic' opening). 6 styles x 5 phrasings = 30 combos.
const INTRO_STYLES = [
  { style: '질문형', patterns: [
    '혹시 이런 경험 있으신가요, 하는 질문으로 시작',
    '만약 ~라면 어땠을까 하는 가정형 질문으로 시작',
    '다들 한 번쯤 궁금했을 질문을 던지며 시작',
    '왜 하필 지금 이 얘기가 나왔을까 하는 물음으로 시작',
    '단도직입적으로 묻는 짧은 질문 한 문장으로 시작'
  ]},
  { style: '통계·숫자 제시형', patterns: [
    '핵심 수치 하나를 툭 던지듯 제시하며 시작',
    '비교 가능한 두 숫자를 나란히 놓으며 시작',
    '숫자보다 그 숫자가 주는 체감을 먼저 언급하며 시작',
    '통계가 나온 시점을 구체적으로 짚으며 시작',
    '숫자의 변화 폭(몇 배, 몇 퍼센트)을 강조하며 시작'
  ]},
  { style: '현장 묘사형', patterns: [
    '구체적 장소와 시간대를 그리듯 묘사하며 시작',
    '누군가의 반응이나 표정을 스케치하듯 시작',
